void permute(string& s, int idx, vector<string>& result) {
    if (idx == s.length()) {
        result.push_back(s);
        return;
    }
    for (int i = idx; i < s.length(); i++) {
        swap(s[idx], s[i]);
        permute(s, idx + 1, result);
        swap(s[idx], s[i]);
    }
}

