    for (int i = 0; i < 9; i++)
        if (grid[row][i] == num || grid[i][col] == num) return false;
    int sr = row - row % 3, sc = col - col % 3;
    for (int i = sr; i < sr + 3; i++)
        for (int j = sc; j < sc + 3; j++)
            if (grid[i][j] == num) return false;
